package com.rylixs.preview;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import android.print.*;
public class MainActivity extends Activity {
 WebView web; String base; ValueCallback<Uri[]> upload; LinearLayout root;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(20,20,20));getWindow().setNavigationBarColor(Color.rgb(20,20,20));base=getPreferences(0).getString("server","http://127.0.0.1:3100");root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(20,20,20));root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,insets.getSystemWindowInsetTop(),0,insets.getSystemWindowInsetBottom());return insets;});LinearLayout bar=new LinearLayout(this);bar.setPadding(8,0,8,0);addButton(bar,"RYLIXS",()->web.loadUrl(base));addButton(bar,"Admin",()->web.loadUrl(base+"/admin"));addButton(bar,"Connect",()->configure());addButton(bar,"Print",()->{PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);pm.print("RYLIXS invoice",web.createPrintDocumentAdapter("RYLIXS"),new PrintAttributes.Builder().build());});root.addView(bar);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setBuiltInZoomControls(false);CookieManager.getInstance().setAcceptCookie(true);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();Uri origin=Uri.parse(base);if((u.getScheme().equals("http")||u.getScheme().equals("https"))&&u.getHost().equals(origin.getHost())&&u.getPort()==origin.getPort())return false;if(u.getScheme().equals("https")||u.getScheme().equals("mailto")||u.getScheme().equals("tel")){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(MainActivity.this,"No app available to open this link",Toast.LENGTH_LONG).show();}}return true;}@Override public void onReceivedError(WebView v,WebResourceRequest req,WebResourceError error){if(req.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Connect to your laptop").setMessage("Start RYLIXS on the laptop, connect your phone by USB, enable USB debugging, then run CONNECT_ANDROID.cmd. Tap Retry once connected.").setPositiveButton("Retry",(d,w)->web.loadUrl(base)).setNeutralButton("Server address",(d,w)->configure()).setNegativeButton("Close",null).show();}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=cb;try{startActivityForResult(params.createIntent(),12);return true;}catch(Exception e){upload=null;return false;}}@Override public boolean onJsConfirm(WebView v,String url,String msg,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(msg).setPositiveButton("Confirm",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});web.loadUrl(base);}
 void addButton(LinearLayout bar,String text,Runnable action){Button b=new Button(this);b.setText(text);b.setTextSize(11);b.setTextColor(Color.rgb(215,184,123));b.setBackgroundColor(Color.TRANSPARENT);bar.addView(b,new LinearLayout.LayoutParams(0,48*getResources().getDisplayMetrics().densityDpi/160,1));b.setOnClickListener(v->action.run());}
 void configure(){EditText address=new EditText(this);address.setSingleLine();address.setInputType(17);address.setText(base);new AlertDialog.Builder(this).setTitle("Local test server").setMessage("USB: http://127.0.0.1:3100\nAndroid emulator: http://10.0.2.2:3100").setView(address).setPositiveButton("Connect",(d,w)->{String value=address.getText().toString().trim().replaceAll("/+$","");Uri u=Uri.parse(value);if(u.getHost()==null||!("http".equals(u.getScheme())||"https".equals(u.getScheme()))||u.getUserInfo()!=null){Toast.makeText(this,"Enter a valid HTTP(S) server address",Toast.LENGTH_LONG).show();return;}base=value;getPreferences(0).edit().putString("server",base).apply();web.loadUrl(base);}).setNegativeButton("Cancel",null).show();}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==12&&upload!=null){upload.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));upload=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onPause(){super.onPause();CookieManager.getInstance().flush();}
 @Override protected void onDestroy(){if(upload!=null)upload.onReceiveValue(null);web.destroy();super.onDestroy();}
}
